WITH metrics AS (SELECT *, LAG(amount) OVER w_recent AS prev_amount, ROW_NUMBER() OVER w_recent AS event_seq FROM transactions WHERE txn_type IN ('DEBIT', 'REFUND', 'FEE') WINDOW w_recent AS (PARTITION BY account_id ORDER BY amount, id)) SELECT DATE_TRUNC('QUARTER', txn_time) AS quarter_start, MIN(txn_time) AS first_txn_time, SIZE(COLLECT_SET(merchant)) AS num_merchants, MAX(txn_time) AS last_txn_time, ROUND(SUM(event_seq) / NULLIF(COUNT(CASE WHEN txn_type = 'FEE' THEN 1 END), 0), 2) AS event_seq_per_fee, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min FROM metrics GROUP BY quarter_start HAVING num_merchants > 1 ORDER BY quarter_start DESC
